38	/** This class represents a 3D region: a set of polyhedrons.
39	 * @version $Id$
40	 * @since 3.0
41	 */
42	public class PolyhedronsSet extends AbstractRegion<Euclidean3D, Euclidean2D> {
43	
44	    /** Build a polyhedrons set representing the whole real line.
45	     */
46	    public PolyhedronsSet() {
47	        super();
48	    }
49	
50	    /** Build a polyhedrons set from a BSP tree.
51	     * <p>The leaf nodes of the BSP tree <em>must</em> have a
52	     * {@code Boolean} attribute representing the inside status of
53	     * the corresponding cell (true for inside cells, false for outside
54	     * cells). In order to avoid building too many small objects, it is
55	     * recommended to use the predefined constants
56	     * {@code Boolean.TRUE} and {@code Boolean.FALSE}</p>
57	     * @param tree inside/outside BSP tree representing the region
58	     */
59	    public PolyhedronsSet(final BSPTree<Euclidean3D> tree) {
60	        super(tree);
61	    }
62	
63	    /** Build a polyhedrons set from a Boundary REPresentation (B-rep).
64	     * <p>The boundary is provided as a collection of {@link
65	     * SubHyperplane sub-hyperplanes}. Each sub-hyperplane has the
66	     * interior part of the region on its minus side and the exterior on
67	     * its plus side.</p>
68	     * <p>The boundary elements can be in any order, and can form
69	     * several non-connected sets (like for example polyhedrons with holes
70	     * or a set of disjoint polyhedrons considered as a whole). In
71	     * fact, the elements do not even need to be connected together
72	     * (their topological connections are not used here). However, if the
73	     * boundary does not really separate an inside open from an outside
74	     * open (open having here its topological meaning), then subsequent
75	     * calls to the {@link Region#checkPoint(Vector) checkPoint} method will
76	     * not be meaningful anymore.</p>
77	     * <p>If the boundary is empty, the region will represent the whole
78	     * space.</p>
79	     * @param boundary collection of boundary elements, as a
80	     * collection of {@link SubHyperplane SubHyperplane} objects
81	     */
82	    public PolyhedronsSet(final Collection<SubHyperplane<Euclidean3D>> boundary) {
83	        super(boundary);
84	    }
85	
86	    /** Build a parallellepipedic box.
87	     * @param xMin low bound along the x direction
88	     * @param xMax high bound along the x direction
89	     * @param yMin low bound along the y direction
90	     * @param yMax high bound along the y direction
91	     * @param zMin low bound along the z direction
92	     * @param zMax high bound along the z direction
93	     */
94	    @SuppressWarnings("unchecked")
95	    public PolyhedronsSet(final double xMin, final double xMax,
96	                          final double yMin, final double yMax,
97	                          final double zMin, final double zMax) {
98	        this(new RegionFactory<Euclidean3D>().buildConvex(
99	            new Plane(new Vector3D(xMin, 0,    0),   Vector3D.MINUS_I),
100	            new Plane(new Vector3D(xMax, 0,    0),   Vector3D.PLUS_I),
101	            new Plane(new Vector3D(0,    yMin, 0),   Vector3D.MINUS_J),
102	            new Plane(new Vector3D(0,    yMax, 0),   Vector3D.PLUS_J),
103	            new Plane(new Vector3D(0,    0,   zMin), Vector3D.MINUS_K),
104	            new Plane(new Vector3D(0,    0,   zMax), Vector3D.PLUS_K)).getTree(false));
105	    }
106	
107	    /** {@inheritDoc} */
108	    @Override
109	    public PolyhedronsSet buildNew(final BSPTree<Euclidean3D> tree) {
110	        return new PolyhedronsSet(tree);
111	    }
112	
113	    /** {@inheritDoc} */
114	    @Override
115	    protected void computeGeometricalProperties() {
116	
117	        // compute the contribution of all boundary facets
118	        getTree(true).visit(new FacetsContributionVisitor());
119	
120	        if (getSize() < 0) {
121	            // the polyhedrons set as a finite outside
122	            // surrounded by an infinite inside
123	            setSize(Double.POSITIVE_INFINITY);
124	            setBarycenter(Vector3D.NaN);
125	        } else {
126	            // the polyhedrons set is finite, apply the remaining scaling factors
127	            setSize(getSize() / 3.0);
128	            setBarycenter(new Vector3D(1.0 / (4 * getSize()), (Vector3D) getBarycenter()));
129	        }
130	
131	    }
132	
133	    /** Visitor computing geometrical properties. */
134	    private class FacetsContributionVisitor implements BSPTreeVisitor<Euclidean3D> {
135	
136	        /** Simple constructor. */
137	        public FacetsContributionVisitor() {
138	            setSize(0);
139	            setBarycenter(new Vector3D(0, 0, 0));
140	        }
141	
142	        /** {@inheritDoc} */
143	        public Order visitOrder(final BSPTree<Euclidean3D> node) {
144	            return Order.MINUS_SUB_PLUS;
145	        }
146	
147	        /** {@inheritDoc} */
148	        public void visitInternalNode(final BSPTree<Euclidean3D> node) {
149	            @SuppressWarnings("unchecked")
150	            final BoundaryAttribute<Euclidean3D> attribute =
151	                (BoundaryAttribute<Euclidean3D>) node.getAttribute();
152	            if (attribute.getPlusOutside() != null) {
153	                addContribution(attribute.getPlusOutside(), false);
154	            }
155	            if (attribute.getPlusInside() != null) {
156	                addContribution(attribute.getPlusInside(), true);
157	            }
158	        }
159	
160	        /** {@inheritDoc} */
161	        public void visitLeafNode(final BSPTree<Euclidean3D> node) {
162	        }
163	
164	        /** Add he contribution of a boundary facet.
165	         * @param facet boundary facet
166	         * @param reversed if true, the facet has the inside on its plus side
167	         */
168	        private void addContribution(final SubHyperplane<Euclidean3D> facet, final boolean reversed) {
169	
170	            final Region<Euclidean2D> polygon = ((SubPlane) facet).getRemainingRegion();
171	            final double area    = polygon.getSize();
172	
173	            if (Double.isInfinite(area)) {
174	                setSize(Double.POSITIVE_INFINITY);
175	                setBarycenter(Vector3D.NaN);
176	            } else {
177	
178	                final Plane    plane  = (Plane) facet.getHyperplane();
179	                final Vector3D facetB = plane.toSpace(polygon.getBarycenter());
180	                double   scaled = area * facetB.dotProduct(plane.getNormal());
181	                if (reversed) {
182	                    scaled = -scaled;
183	                }
184	
185	                setSize(getSize() + scaled);
186	                setBarycenter(new Vector3D(1.0, (Vector3D) getBarycenter(), scaled, facetB));
187	
188	            }
189	
190	        }
191	
192	    }
193	
194	    /** Get the first sub-hyperplane crossed by a semi-infinite line.
195	     * @param point start point of the part of the line considered
196	     * @param line line to consider (contains point)
197	     * @return the first sub-hyperplaned crossed by the line after the
198	     * given point, or null if the line does not intersect any
199	     * sub-hyperplaned
200	     */
201	    public SubHyperplane<Euclidean3D> firstIntersection(final Vector3D point, final Line line) {
202	        return recurseFirstIntersection(getTree(true), point, line);
203	    }
204	
205	    /** Get the first sub-hyperplane crossed by a semi-infinite line.
206	     * @param node current node
207	     * @param point start point of the part of the line considered
208	     * @param line line to consider (contains point)
209	     * @return the first sub-hyperplaned crossed by the line after the
210	     * given point, or null if the line does not intersect any
211	     * sub-hyperplaned
212	     */
213	    private SubHyperplane<Euclidean3D> recurseFirstIntersection(final BSPTree<Euclidean3D> node,
214	                                                                final Vector3D point,
215	                                                                final Line line) {
216	
217	        final SubHyperplane<Euclidean3D> cut = node.getCut();
218	        if (cut == null) {
219	            return null;
220	        }
221	        final BSPTree<Euclidean3D> minus = node.getMinus();
222	        final BSPTree<Euclidean3D> plus  = node.getPlus();
223	        final Plane               plane = (Plane) cut.getHyperplane();
224	
225	        // establish search order
226	        final double offset = plane.getOffset(point);
227	        final boolean in    = FastMath.abs(offset) < 1.0e-10;
228	        final BSPTree<Euclidean3D> near;
229	        final BSPTree<Euclidean3D> far;
230	        if (offset < 0) {
231	            near = minus;
232	            far  = plus;
233	        } else {
234	            near = plus;
235	            far  = minus;
236	        }
237	
238	        if (in) {
239	            // search in the cut hyperplane
240	            final SubHyperplane<Euclidean3D> facet = boundaryFacet(point, node);
241	            if (facet != null) {
242	                return facet;
243	            }
244	        }
245	
246	        // search in the near branch
247	        final SubHyperplane<Euclidean3D> crossed = recurseFirstIntersection(near, point, line);
248	        if (crossed != null) {
249	            return crossed;
250	        }
251	
252	        if (!in) {
253	            // search in the cut hyperplane
254	            final Vector3D hit3D = plane.intersection(line);
255	            if (hit3D != null) {
256	                final SubHyperplane<Euclidean3D> facet = boundaryFacet(hit3D, node);
257	                if (facet != null) {
258	                    return facet;
259	                }
260	            }
261	        }
262	
263	        // search in the far branch
264	        return recurseFirstIntersection(far, point, line);
265	
266	    }
267	
268	    /** Check if a point belongs to the boundary part of a node.
269	     * @param point point to check
270	     * @param node node containing the boundary facet to check
271	     * @return the boundary facet this points belongs to (or null if it
272	     * does not belong to any boundary facet)
273	     */
274	    private SubHyperplane<Euclidean3D> boundaryFacet(final Vector3D point,
275	                                                     final BSPTree<Euclidean3D> node) {
276	        final Vector2D point2D = ((Plane) node.getCut().getHyperplane()).toSubSpace(point);
277	        @SuppressWarnings("unchecked")
278	        final BoundaryAttribute<Euclidean3D> attribute =
279	            (BoundaryAttribute<Euclidean3D>) node.getAttribute();
280	        if ((attribute.getPlusOutside() != null) &&
281	            (((SubPlane) attribute.getPlusOutside()).getRemainingRegion().checkPoint(point2D) == Location.INSIDE)) {
282	            return attribute.getPlusOutside();
283	        }
284	        if ((attribute.getPlusInside() != null) &&
285	            (((SubPlane) attribute.getPlusInside()).getRemainingRegion().checkPoint(point2D) == Location.INSIDE)) {
286	            return attribute.getPlusInside();
287	        }
288	        return null;
289	    }
290	
291	    /** Rotate the region around the specified point.
292	     * <p>The instance is not modified, a new instance is created.</p>
293	     * @param center rotation center
294	     * @param rotation vectorial rotation operator
295	     * @return a new instance representing the rotated region
296	     */
297	    public PolyhedronsSet rotate(final Vector3D center, final Rotation rotation) {
298	        return (PolyhedronsSet) applyTransform(new RotationTransform(center, rotation));
299	    }
