84	    /** Copy constructor.
85	     * <p>The instance created is completely independant of the original
86	     * one. A deep copy is used, none of the underlying object are
87	     * shared.</p>
88	     * @param plane plane to copy
89	     */
90	    public Plane(final Plane plane) {
91	        originOffset = plane.originOffset;
92	        origin = plane.origin;
93	        u      = plane.u;
94	        v      = plane.v;
