97	
98	    /** Copy the instance.
99	     * <p>The instance created is completely independant of the original
100	     * one. A deep copy is used, none of the underlying objects are
101	     * shared (except for immutable objects).</p>
102	     * @return a new hyperplane, copy of the instance
103	     */
104	    public Plane copySelf() {
105	        return new Plane(this);
106	    }
107	
108	    /** Reset the instance as if built from a point and a normal.
109	     * @param p point belonging to the plane
110	     * @param normal normal direction to the plane
111	     */
112	    public void reset(final Vector3D p, final Vector3D normal) {
113	        setNormal(normal);
114	        originOffset = -p.dotProduct(w);
115	        setFrame();
116	    }
117	
118	    /** Reset the instance from another one.
119	     * <p>The updated instance is completely independant of the original
120	     * one. A deep reset is used none of the underlying object is
121	     * shared.</p>
122	     * @param original plane to reset from
123	     */
124	    public void reset(final Plane original) {
125	        originOffset = original.originOffset;
126	        origin       = original.origin;
127	        u            = original.u;
128	        v            = original.v;
129	        w            = original.w;
130	    }
