132	    /** Set the normal vactor.
133	     * @param normal normal direction to the plane (will be copied)
134	     * @exception MathArithmeticException if the normal norm is too small
135	     */
136	    private void setNormal(final Vector3D normal) {
137	        final double norm = normal.getNorm();
138	        if (norm < 1.0e-10) {
139	            throw new MathArithmeticException(LocalizedFormats.ZERO_NORM);
140	        }
141	        w = new Vector3D(1.0 / norm, normal);
142	    }
