198	    /** Revert the plane.
199	     * <p>Replace the instance by a similar plane with opposite orientation.</p>
200	     * <p>The new plane frame is chosen in such a way that a 3D point that had
201	     * {@code (x, y)} in-plane coordinates and {@code z} offset with
202	     * respect to the plane and is unaffected by the change will have
203	     * {@code (y, x)} in-plane coordinates and {@code -z} offset with
204	     * respect to the new plane. This means that the {@code u} and {@code v}
205	     * vectors returned by the {@link #getU} and {@link #getV} methods are exchanged,
206	     * and the {@code w} vector returned by the {@link #getNormal} method is
207	     * reversed.</p>
208	     */
209	    public void revertSelf() {
210	        final Vector3D tmp = u;
211	        u = v;
212	        v = tmp;
213	        w = w.negate();
214	        originOffset = -originOffset;
215	    }
