217	    /** Transform a 3D space point into an in-plane point.
218	     * @param point point of the space (must be a {@link Vector3D
219	     * Vector3D} instance)
220	     * @return in-plane point (really a {@link
221	     * org.apache.commons.math3.geometry.euclidean.twod.Vector2D Vector2D} instance)
222	     * @see #toSpace
223	     */
224	    public Vector2D toSubSpace(final Vector<Euclidean3D> point) {
225	        return new Vector2D(point.dotProduct(u), point.dotProduct(v));
226	    }
