250	    /** Check if the instance is similar to another plane.
251	     * <p>Planes are considered similar if they contain the same
252	     * points. This does not mean they are equal since they can have
253	     * opposite normals.</p>
254	     * @param plane plane to which the instance is compared
255	     * @return true if the planes are similar
256	     */
257	    public boolean isSimilarTo(final Plane plane) {
258	        final double angle = Vector3D.angle(w, plane.w);
259	        return ((angle < 1.0e-10) && (FastMath.abs(originOffset - plane.originOffset) < 1.0e-10)) ||
260	               ((angle > (FastMath.PI - 1.0e-10)) && (FastMath.abs(originOffset + plane.originOffset) < 1.0e-10));
261	    }
