263	    /** Rotate the plane around the specified point.
264	     * <p>The instance is not modified, a new instance is created.</p>
265	     * @param center rotation center
266	     * @param rotation vectorial rotation operator
267	     * @return a new plane
268	     */
269	    public Plane rotate(final Vector3D center, final Rotation rotation) {
270	
271	        final Vector3D delta = origin.subtract(center);
272	        final Plane plane = new Plane(center.add(rotation.applyTo(delta)),
273	                                rotation.applyTo(w));
274	
275	        // make sure the frame is transformed as desired
276	        plane.u = rotation.applyTo(u);
277	        plane.v = rotation.applyTo(v);
278	
279	        return plane;
280	
281	    }
