300	    /** Get the intersection of a line with the instance.
301	     * @param line line intersecting the instance
302	     * @return intersection point between between the line and the
303	     * instance (null if the line is parallel to the instance)
304	     */
305	    public Vector3D intersection(final Line line) {
306	        final Vector3D direction = line.getDirection();
307	        final double   dot       = w.dotProduct(direction);
308	        if (FastMath.abs(dot) < 1.0e-10) {
309	            return null;
310	        }
311	        final Vector3D point = line.toSpace(Vector1D.ZERO);
312	        final double   k     = -(originOffset + w.dotProduct(point)) / dot;
313	        return new Vector3D(1.0, point, k, direction);
314	    }
315	
316	    /** Build the line shared by the instance and another plane.
317	     * @param other other plane
318	     * @return line at the intersection of the instance and the
319	     * other plane (really a {@link Line Line} instance)
320	     */
321	    public Line intersection(final Plane other) {
322	        final Vector3D direction = Vector3D.crossProduct(w, other.w);
323	        if (direction.getNorm() < 1.0e-10) {
324	            return null;
325	        }
326	        final Vector3D point = intersection(this, other, new Plane(direction));
327	        return new Line(point, point.add(direction));
328	    }
329	
330	    /** Get the intersection point of three planes.
331	     * @param plane1 first plane1
332	     * @param plane2 second plane2
333	     * @param plane3 third plane2
334	     * @return intersection point of three planes, null if some planes are parallel
335	     */
336	    public static Vector3D intersection(final Plane plane1, final Plane plane2, final Plane plane3) {
337	
338	        // coefficients of the three planes linear equations
339	        final double a1 = plane1.w.getX();
340	        final double b1 = plane1.w.getY();
341	        final double c1 = plane1.w.getZ();
342	        final double d1 = plane1.originOffset;
343	
344	        final double a2 = plane2.w.getX();
345	        final double b2 = plane2.w.getY();
346	        final double c2 = plane2.w.getZ();
347	        final double d2 = plane2.originOffset;
348	
349	        final double a3 = plane3.w.getX();
350	        final double b3 = plane3.w.getY();
351	        final double c3 = plane3.w.getZ();
352	        final double d3 = plane3.originOffset;
353	
354	        // direct Cramer resolution of the linear system
355	        // (this is still feasible for a 3x3 system)
356	        final double a23         = b2 * c3 - b3 * c2;
357	        final double b23         = c2 * a3 - c3 * a2;
358	        final double c23         = a2 * b3 - a3 * b2;
359	        final double determinant = a1 * a23 + b1 * b23 + c1 * c23;
360	        if (FastMath.abs(determinant) < 1.0e-10) {
361	            return null;
362	        }
363	
364	        final double r = 1.0 / determinant;
365	        return new Vector3D(
366	                            (-a23 * d1 - (c1 * b3 - c3 * b1) * d2 - (c2 * b1 - c1 * b2) * d3) * r,
367	                            (-b23 * d1 - (c3 * a1 - c1 * a3) * d2 - (c1 * a2 - c2 * a1) * d3) * r,
368	                            (-c23 * d1 - (b1 * a3 - b3 * a1) * d2 - (b2 * a1 - b1 * a2) * d3) * r);
369	
370	    }
371	
372	    /** Build a region covering the whole hyperplane.
373	     * @return a region covering the whole hyperplane
374	     */
375	    public SubPlane wholeHyperplane() {
376	        return new SubPlane(this, new PolygonsSet());
377	    }
378	
379	    /** Build a region covering the whole space.
380	     * @return a region containing the instance (really a {@link
381	     * PolyhedronsSet PolyhedronsSet} instance)
382	     */
383	    public PolyhedronsSet wholeSpace() {
384	        return new PolyhedronsSet();
385	    }
386	
387	    /** Check if the instance contains a point.
388	     * @param p point to check
389	     * @return true if p belongs to the plane
390	     */
391	    public boolean contains(final Vector3D p) {
392	        return FastMath.abs(getOffset(p)) < 1.0e-10;
393	    }
394	
395	    /** Get the offset (oriented distance) of a parallel plane.
396	     * <p>This method should be called only for parallel planes otherwise
397	     * the result is not meaningful.</p>
398	     * <p>The offset is 0 if both planes are the same, it is
399	     * positive if the plane is on the plus side of the instance and
400	     * negative if it is on the minus side, according to its natural
401	     * orientation.</p>
402	     * @param plane plane to check
403	     * @return offset of the plane
404	     */
405	    public double getOffset(final Plane plane) {
406	        return originOffset + (sameOrientationAs(plane) ? -plane.originOffset : plane.originOffset);
407	    }
408	
409	    /** Get the offset (oriented distance) of a point.
410	     * <p>The offset is 0 if the point is on the underlying hyperplane,
411	     * it is positive if the point is on one particular side of the
412	     * hyperplane, and it is negative if the point is on the other side,
413	     * according to the hyperplane natural orientation.</p>
414	     * @param point point to check
415	     * @return offset of the point
416	     */
417	    public double getOffset(final Vector<Euclidean3D> point) {
418	        return point.dotProduct(w) + originOffset;
419	    }
420	
421	    /** Check if the instance has the same orientation as another hyperplane.
422	     * @param other other hyperplane to check against the instance
423	     * @return true if the instance and the other hyperplane have
424	     * the same orientation
425	     */
426	    public boolean sameOrientationAs(final Hyperplane<Euclidean3D> other) {
427	        return (((Plane) other).w).dotProduct(w) > 0.0;
428	    }
429	
430	}
