391	        public boolean equals(final Object other) {
392	            if (this == other) {
393	                return true;
394	            } else if (other instanceof ComparableSegment) {
395	                return compareTo((ComparableSegment) other) == 0;
396	            } else {
397	                return false;
398	            }
399	        }
